  "phi > 40 degrees: factors are very sensitive to phi; confirm phi by testing.": "φ > 40°: faktor sangat peka terhadap φ; pastikan φ dengan pengujian.",
  "Loose granular soil: local or punching shear may govern; settlement likely controls.": "Tanah granular lepas: keruntuhan geser lokal atau pons bisa menentukan; penurunan kemungkinan yang mengendalikan.",
  "Vertical centric load on level ground assumed; no inclination, eccentricity, base or slope factors.": "Diasumsikan beban vertikal sentris di tanah datar; tanpa faktor kemiringan beban, eksentrisitas, dasar, atau lereng.",
  "Settlement is not checked; allowable pressure may be limited by settlement.": "Penurunan tidak diperiksa; tekanan izin bisa dibatasi oleh penurunan.",
  "Preliminary estimate only; results must be checked by a qualified geotechnical engineer.": "Hanya perkiraan awal; hasil harus diperiksa oleh ahli geoteknik yang kompeten.",
  "Pile length is shorter than its diameter; check the input.": "Panjang tiang lebih pendek dari diameternya; periksa masukan.",
  "No SPT within one diameter of the tip; nearest SPT used for Np.": "Tidak ada SPT dalam jarak satu diameter dari ujung tiang; SPT terdekat dipakai untuk Np.",
  "Tip N values above 50 capped at 50.": "Nilai N ujung di atas 50 dibatasi 50.",
  "No SPT along the shaft outside the tip zone; tip-zone SPTs used for the shaft.": "Tidak ada SPT di sepanjang selimut di luar zona ujung; SPT zona ujung dipakai untuk selimut.",
  "Shaft N values limited to 3 <= N <= 50; SPTs used for the tip are excluded from the shaft.": "Nilai N selimut dibatasi 3 ≤ N ≤ 50; SPT untuk ujung tidak dipakai untuk selimut.",
  "Shaft computed in 1 m slices from the ground surface; slice N is the mean of SPTs in the slice, else the nearest SPT.": "Selimut dihitung per irisan 1 m dari muka tanah; N irisan adalah rata-rata SPT dalam irisan, atau SPT terdekat.",
  "Negative skin friction, group effects, uplift and settlement are not considered.": "Gesekan negatif, efek kelompok, gaya cabut, dan penurunan tidak diperhitungkan.",
  "Structural capacity of the pile section must be checked separately.": "Kapasitas struktur penampang tiang harus diperiksa tersendiri.",
  "gamma_sat not given for a layer below the water table; gamma used (conservative).": "γsat tidak diisi untuk lapisan di bawah muka air tanah; dipakai γ (konservatif).",
  "Primary consolidation only; immediate and secondary compression are not included.": "Hanya konsolidasi primer; penurunan segera dan kompresi sekunder tidak termasuk.",
  "Stress increase by the approximate 2:1 method; footing assumed flexible.": "Penambahan tegangan dengan metode pendekatan 2:1; fondasi dianggap fleksibel.",
  "Layers are split into sublayers of at most 1 m; stresses taken at sublayer mid-depth.": "Lapisan dibagi menjadi sublapisan maksimal 1 m; tegangan diambil di tengah sublapisan.",
  "Borehole diameter outside 65-200 mm; CB taken at the nearest end of the range.": "Diameter lubang bor di luar 65–200 mm; CB diambil dari batas rentang terdekat.",
  "Sampler correction CS = 1.0 (standard sampler with liners).": "Koreksi sampler CS = 1,0 (sampler standar dengan liner).",
  "Sampler correction CS = 1.0 assumed; a sampler without liners may justify CS = 1.1-1.3 (1.0 is conservative).": "Koreksi sampler CS = 1,0 diasumsikan; sampler tanpa liner bisa memakai CS = 1,1–1,3 (1,0 konservatif).",
  "CL-ML evaluated as sand-like (low plasticity); fines content 60% assumed.": "CL-ML dievaluasi seperti pasir (plastisitas rendah); kadar butir halus 60% diasumsikan.",
  "Fines content not given for some layers; default by USCS group used.": "Kadar butir halus tidak diisi untuk beberapa lapisan; dipakai nilai bawaan menurut kelompok USCS.",
  "Liquefiable layers found: assess settlement, lateral spreading and loss of pile/footing support.": "Ditemukan lapisan berpotensi likuifaksi: kaji penurunan, lateral spreading, dan hilangnya daya dukung tiang/fondasi.",
  "Rod length taken as SPT depth + rod_extra_m for CR.": "Panjang batang untuk CR diambil kedalaman SPT + rod_extra_m.",
  "SPTs deeper than 20 m are not evaluated.": "SPT lebih dalam dari 20 m tidak dievaluasi.",
