  "Site class SF (liquefiable, sensitive or very soft thick clay) needs a site-specific analysis; check it separately.": "Kelas situs SF (berpotensi likuifaksi, sensitif, atau lempung sangat lunak dan tebal) memerlukan analisis spesifik situs; periksa tersendiri.",
