  "Unit weight is taken as constant with depth; pore pressure is hydrostatic below the groundwater level.": "Berat isi dianggap tetap terhadap kedalaman; tekanan pori hidrostatis di bawah muka air tanah.",
  "Use PGA_M as amax in the liquefaction analysis.": "Pakai PGA_M sebagai amax pada analisis likuifaksi.",
  "Very dense soil and soft rock": "Tanah sangat padat dan batuan lunak",
  "qt = qc + u2 (1 − a); without u2, qt = qc.": "qt = qc + u2 (1 − a); tanpa u2, qt = qc.",
  "su = (qt − σv0) / Nkt for Ic > 2.6; φ' = 17.6 + 11 log Qtn (Kulhawy & Mayne) for Ic < 2.6.": "su = (qt − σv0) / Nkt untuk Ic > 2,6; φ' = 17,6 + 11 log Qtn (Kulhawy & Mayne) untuk Ic < 2,6.",
