  "Empty tables use the company defaults shown on this page, to be confirmed by the pricing committee. Fill them in to change them.": "Tabel yang kosong memakai nilai bawaan perusahaan seperti tercantum di halaman ini, menunggu penetapan komite penawaran harga. Isi tabelnya bila ingin mengubah.",
  "Copy the company defaults into the empty tables": "Salin nilai bawaan perusahaan ke tabel yang kosong",
  "Project difficulty factors, risk premium by difficulty index, margin, maximum cost ratio, approval authority and receivables rules.": "Faktor indeks kesulitan proyek, premi risiko menurut indeks, marjin, rasio biaya maksimum, kewenangan pemutus, dan ketentuan penagihan piutang.",
  "Enter the company name in the company settings first.": "Isi nama perusahaan di pengaturan perusahaan terlebih dahulu.",
