  "Commercial position, receivables, projects against budget, equipment, purchasing, assets and people in one place.": "Posisi komersial, piutang, proyek terhadap anggaran, peralatan, pengadaan, aset dan SDM dalam satu halaman.",
  "{n} documents are waiting for you in the approval flow.": "{n} dokumen menunggu tindakan Anda dalam alur persetujuan.",
  "Open approvals": "Buka persetujuan",
  "Pricing & budgeting decisions": "Pricing & Budgeting Decision (PBD)",
  "Government cost reference": "Acuan biaya pemerintah",
  "Checks the price against the government rules: AHSP construction work adds 10–15% indirect cost (overhead and profit) to the direct cost; consultancy keeps direct cost at most 40% of the contract value. Empty: company pricing only.": "Harga dicek terhadap ketentuan pemerintah: pekerjaan konstruksi berbasis AHSP menambahkan biaya tidak langsung (overhead dan keuntungan) 10–15% dari biaya langsung; jasa konsultansi menjaga biaya langsung non-personel paling banyak 40% dari nilai kontrak. Kosongkan bila hanya memakai harga perusahaan.",
  "Government construction work: AHSP (Permen PUPR 8/2023)": "Pekerjaan konstruksi pemerintah: AHSP (Permen PUPR 8/2023)",
  "Government consultancy: billing rates and direct cost (INKINDO, LKPP)": "Jasa konsultansi pemerintah: billing rate dan biaya langsung (INKINDO, LKPP)",
  "Risk premium and margin (% of the ABP)": "Premi risiko dan margin (% dari ABP)",
  "ABP + 15% indirect cost (AHSP reference)": "ABP + biaya tidak langsung 15% (acuan AHSP)",
  "Non-personnel cost (% of the bid price)": "Biaya non-personel (% dari harga penawaran)",
  "Risk premium and margin come to {pct}% of the ABP, above the 10–15% indirect cost (overhead and profit) on direct cost that owner's estimates use under Permen PUPR 8/2023 Art. 11(3): the bid may exceed the HPS.": "Premi risiko dan margin mencapai {pct}% dari ABP, di atas biaya tidak langsung (overhead dan keuntungan) 10–15% dari biaya langsung yang dipakai owner dalam menyusun HPS menurut Permen PUPR 8/2023 Pasal 11 ayat (3): penawaran berisiko melampaui HPS.",
  "Risk premium and margin come to {pct}% of the ABP, below the 10–15% indirect cost of Permen PUPR 8/2023 Art. 11(3).": "Premi risiko dan margin hanya {pct}% dari ABP, di bawah biaya tidak langsung 10–15% menurut Permen PUPR 8/2023 Pasal 11 ayat (3).",
  "Add the personnel (labour) lines: consultancy prices are built from personnel billing rates and direct costs.": "Tambahkan baris personel (tenaga kerja): harga jasa konsultansi disusun dari billing rate personel dan biaya langsung.",
  "Non-personnel cost is {pct}% of the bid price. Consultancy guidance (INKINDO 2025, after LKPP Reg. 12/2021) expects at most 40% for most work, except survey, measurement and mapping work where direct cost dominates: explain the share in the proposal.": "Biaya non-personel {pct}% dari harga penawaran. Pedoman konsultansi (INKINDO 2025, mengacu Peraturan LKPP 12/2021) membatasinya paling banyak 40% untuk kebanyakan pekerjaan, kecuali pekerjaan survei, pengukuran dan pemetaan yang biaya langsungnya dominan: jelaskan porsinya dalam proposal.",
  "Government client: choose the government cost reference to check the price against the AHSP or consultancy rules.": "Klien pemerintah: pilih acuan biaya pemerintah agar harga dicek terhadap ketentuan AHSP atau jasa konsultansi.",
  "AHSP reference: Permen PUPR 8/2023 Art. 11(3) sets indirect cost (overhead and profit) at 10–15% of the direct cost for owner's estimates of construction work financed by the state; the ABP here also holds costs AHSP counts as overhead.": "Acuan AHSP: Permen PUPR 8/2023 Pasal 11 ayat (3) menetapkan biaya tidak langsung (biaya umum dan keuntungan) 10–15% dari biaya langsung untuk perkiraan biaya pekerjaan konstruksi yang dibiayai keuangan negara; ABP di sini juga memuat biaya yang dalam AHSP tergolong biaya umum.",
  "Consultancy reference: billing rate = basic salary + social charges + overhead + profit (INKINDO 2025); expert pay not below Kepmen PU 33/KPTS/M/2025; direct cost normally at most 40% of the contract value excl. VAT.": "Acuan jasa konsultansi: billing rate = gaji dasar + beban sosial + overhead + keuntungan (INKINDO 2025); remunerasi tenaga ahli tidak di bawah Kepmen PU 33/KPTS/M/2025; biaya langsung non-personel umumnya paling banyak 40% dari nilai kontrak sebelum PPN.",
  "Budget at completion (BAC)": "Anggaran total (BAC)",
