  "Impairment (PSAK 236 Penurunan Nilai Aset, formerly PSAK 48; IAS 36 paragraphs 9 and 12): at each reporting date check for signs that the asset may be impaired, such as physical damage or obsolescence, the asset becoming idle, worse economic performance than expected, a decline in its value, or adverse changes in technology, market or law. When there is a sign, estimate the recoverable amount.": "Penurunan nilai (PSAK 236 Penurunan Nilai Aset, dahulu PSAK 48; IAS 36 paragraf 9 dan 12): setiap tanggal pelaporan periksa indikasi penurunan nilai aset, misalnya rusak fisik atau usang, aset menganggur, kinerja ekonomi lebih buruk dari perkiraan, nilainya turun, atau perubahan merugikan di bidang teknologi, pasar, atau hukum. Bila ada indikasi, estimasi jumlah terpulihkannya.",
