  "MTBF (days)": "MTBF (hari)",
  "MTBF, mean operating time between failures (IEC 60050-192:2015, 192-05-13; EN 13306): up time in the period ÷ number of failures (repair work orders reported in the period). Operating hours are not logged, so up time is counted in calendar days.": "MTBF, rata-rata waktu operasi antar kerusakan (IEC 60050-192:2015, 192-05-13; EN 13306): up time dalam periode ÷ jumlah kerusakan (work order perbaikan yang dilaporkan dalam periode). Jam operasi tidak dicatat, jadi up time dihitung dalam hari kalender.",
  "MTTR": "MTTR",
  "MTTR (days)": "MTTR (hari)",
  "MTTR, mean time to restoration (IEC 60050-192:2015, 192-07-23; EN 13306): the average time from the failure (taken as the day the repair was reported, 192-07-06 note 1) until the equipment was restored, over the repairs completed in the period, unless the downtime was entered by hand.": "MTTR, rata-rata waktu pemulihan (IEC 60050-192:2015, 192-07-23; EN 13306): rata-rata waktu sejak kerusakan (diambil tanggal perbaikan dilaporkan, 192-07-06 catatan 1) sampai alat pulih, dari perbaikan yang selesai dalam periode, kecuali downtime diisi manual.",
