  "Physical damage or obsolescence": "Rusak fisik atau usang",
  "PM compliance": "PM compliance",
  "PM compliance (%)": "PM compliance (%)",
  "PM compliance (after SMRP metric 5.4.14 as quoted on the SMRP member forum): a scheduled work order is on time when completed by its planned date plus 20% of the service or calibration interval, at most 28 days; work orders past that window and still open count as late; those still inside it are not counted yet.": "PM compliance (mengacu metrik SMRP 5.4.14 sebagaimana dikutip di forum anggota SMRP): work order terjadwal dianggap tepat waktu bila selesai paling lambat tanggal rencana ditambah 20% interval servis atau kalibrasi, maksimal 28 hari; yang lewat batas itu dan masih terbuka dihitung terlambat; yang masih di dalam batas belum dihitung.",
  "Preventive share": "Porsi preventif",
  "Preventive share (%)": "Porsi preventif (%)",
  "Preventive share of completed work orders": "Porsi preventif dari work order yang selesai",
  "Preventive share: preventive, calibration and inspection work orders (maintenance carried out to a schedule, IEC 60050-192 192-06-05 and 192-06-12) as a share of all work orders completed in the period. SMRP measures planned work in labour hours (metric 5.3.1); labour hours are not recorded here, so work orders are counted.": "Porsi preventif: work order preventif, kalibrasi, dan inspeksi (perawatan terjadwal, IEC 60050-192 192-06-05 dan 192-06-12) dibanding semua work order yang selesai dalam periode. SMRP mengukur planned work dalam jam kerja (metrik 5.3.1); jam kerja tidak dicatat di sini, jadi yang dihitung jumlah work order.",
