  "The higher of fair value less costs of disposal and value in use; only when there is a sign of impairment.": "Yang lebih tinggi antara nilai wajar dikurangi biaya pelepasan dan nilai pakai; diisi hanya bila ada indikasi penurunan nilai.",
  "The period starts after it ends": "Awal periode jatuh setelah akhir periode",
  "The person who approved the procurement card also raised this purchase order: have another person raise or check it (segregation of duties)": "Orang yang menyetujui kartu procurement juga membuat PO ini: minta orang lain membuat atau memeriksanya (pemisahan tugas)",
