  "The results changed after they were authorised: review and authorise them again (ISO/IEC 17025 7.8.1.1)": "Hasil berubah setelah diotorisasi: kaji dan otorisasi ulang (ISO/IEC 17025 7.8.1.1)",
  "The results must be authorised by someone other than the person who entered them": "Hasil harus diotorisasi oleh orang lain, bukan yang menginputnya",
  "The results must be reviewed and authorised before the test is marked done (ISO/IEC 17025 7.8.1.1)": "Hasil harus dikaji dan diotorisasi sebelum uji ditandai selesai (ISO/IEC 17025 7.8.1.1)",
