  "When a recoverable amount below the book value is entered, the difference is shown as an indicated impairment loss. It is not deducted in the schedules above: the accountant books it and adjusts the later depreciation.": "Bila jumlah terpulihkan yang diisi lebih rendah dari nilai buku, selisihnya ditampilkan sebagai indikasi rugi penurunan nilai. Selisih ini tidak dikurangkan di jadwal di atas: akuntan yang mencatatnya dan menyesuaikan penyusutan berikutnya.",
  "Which earlier results or reports could be affected, and what the check found.": "Hasil atau laporan sebelumnya yang mungkin terdampak, dan apa hasil pemeriksaannya.",
  "Who has what interest": "Siapa dan apa kepentingannya",
  "Why it happened (e.g. 5 whys); whether similar nonconformities exist or could occur.": "Mengapa terjadi (mis. 5 why); apakah ada atau bisa muncul ketidaksesuaian serupa.",
