  "Request sent. Once an administrator approves it, sign in with this email and the password you just chose. Ask your administrator if it takes long.": "Permintaan terkirim. Setelah disetujui admin, masuk dengan email ini dan kata sandi yang baru saja Anda buat. Kalau lama belum disetujui, hubungi admin Anda.",
