  "Required factors of safety": "Faktor keamanan syarat",
  "Required values: overturning ≥ 2.0, sliding ≥ 1.5, bearing ≥ 3.0, e ≤ B/6 static; ≥ 1.5, ≥ 1.1, ≥ 2.0 and e ≤ B/4 seismic, as common practice with SNI 8460:2017. Change them to the project specification where it differs.": "Nilai syarat bawaan: guling ≥ 2,0, geser ≥ 1,5, daya dukung ≥ 3,0, e ≤ B/6 untuk statik; ≥ 1,5, ≥ 1,1, ≥ 2,0 dan e ≤ B/4 untuk gempa, sesuai praktik umum dengan SNI 8460:2017. Sesuaikan bila spesifikasi proyek berbeda.",
  "Retaining wall stability (overturning, sliding, bearing)": "Stabilitas dinding penahan tanah (guling, geser, daya dukung)",
