  "The default values reproduce the cantilever wall example in Das, Principles of Foundation Engineering (FS overturning 2.98, sliding 2.73, bearing 3.03).": "Nilai bawaan mengikuti contoh dinding kantilever dalam Das, Principles of Foundation Engineering (FS guling 2,98, geser 2,73, daya dukung 3,03).",
  "The resultant falls outside the base: the wall overturns. Widen the base or lengthen the heel.": "Resultan jatuh di luar pelat dasar: dinding terguling. Perlebar pelat dasar atau perpanjang heel.",
