  "Controls for the high-risk JSA steps": "Pengendalian untuk tahap JSA berisiko tinggi",
  "Excavations 1.5 m (5 ft) deep or more need sloping, benching or shoring unless they are entirely in stable rock (29 CFR 1926.652).": "Galian sedalam 1,5 m (5 ft) atau lebih wajib dilandaikan, dibuat berteras atau diturap, kecuali seluruhnya di batuan stabil (29 CFR 1926.652).",
  "Excavations deeper than 6.1 m (20 ft) need a protective system designed by a registered professional engineer (29 CFR 1926.652(b)).": "Galian lebih dalam dari 6,1 m (20 ft) wajib memakai sistem pengaman yang dirancang insinyur profesional bersertifikat (29 CFR 1926.652(b)).",
  "Excavation shallower than 1.5 m: no protective system is required unless a competent person sees signs of cave-in (29 CFR 1926.652(a)).": "Galian kurang dari 1,5 m: tidak wajib sistem pengaman kecuali orang yang kompeten melihat tanda longsoran (29 CFR 1926.652(a)).",
  "Add the job safety analysis (step, hazard, control, PPE, responsible) before work starts.": "Lengkapi JSA (tahap, bahaya, pengendalian, APD, penanggung jawab) sebelum pekerjaan dimulai.",
  "Work must not start until the critical items answered No are corrected and the checklist is signed again.": "Pekerjaan tidak boleh dimulai sebelum item kritis yang dijawab Tidak diperbaiki dan checklist ditandatangani ulang.",
  "Answer every critical item (Yes, No or N.A.) before work starts.": "Jawab semua item kritis (Ya, Tidak atau T/A) sebelum pekerjaan dimulai.",
  "Work may start; close the items answered No as soon as possible.": "Pekerjaan boleh dimulai; selesaikan item yang dijawab Tidak secepatnya.",
  "Critical items stop the work when answered No; the other items need an action but do not stop the work.": "Item kritis menghentikan pekerjaan bila dijawab Tidak; item lain perlu tindakan tetapi tidak menghentikan pekerjaan.",
  "Pre-drilling checklist and permit to work (29 CFR 1926 Subpart P, OSHA 3071 job hazard analysis, ISO 45001:2018)": "Checklist pra-pengeboran dan izin kerja (29 CFR 1926 Subpart P, OSHA 3071 job hazard analysis, ISO 45001:2018)",
