  "Sand cone field density": "Kepadatan lapangan sand cone",
  "Field density of compacted fill or subgrade with the sand cone: hole volume from calibrated sand, dry density and relative compaction against the Proctor maximum, pass or fail per point.": "Kepadatan lapangan timbunan atau tanah dasar dengan sand cone: volume lubang dari pasir terkalibrasi, berat isi kering dan derajat kepadatan terhadap Proctor maksimum, lulus atau tidak per titik.",
  "Sand and cone calibration": "Kalibrasi pasir dan konus",
  "Bulk density of the sand ρ sand (g/cm³)": "Berat isi pasir ρ pasir (g/cm³)",
  "Empty: worked out from the calibration container below.": "Kosong: dihitung dari wadah kalibrasi di bawah.",
  "Calibration container": "Wadah kalibrasi",
  "Sand filling the container (g)": "Pasir pengisi wadah (g)",
  "Container volume (cm³)": "Volume wadah (cm³)",
  "Sand filling the cone and base plate (g)": "Pasir pengisi konus dan pelat dasar (g)",
