  "Jar + sand after (g)": "Botol + pasir akhir (g)",
  "Maximum dry density γd,max (g/cm³)": "Berat isi kering maksimum γd,max (g/cm³)",
  "From the Proctor test of the same material; use Pick a Proctor test to copy it from the laboratory.": "Dari uji Proctor material yang sama; pakai Pilih uji Proctor untuk menyalinnya dari laboratorium.",
  "Proctor test": "Uji Proctor",
  "Laboratory test or report the γd,max comes from.": "Uji atau laporan laboratorium asal γd,max.",
  "Required relative compaction (%)": "Derajat kepadatan disyaratkan (%)",
  "e.g. 95 % of standard Proctor for subgrade, 90 % for common fill.": "mis. 95 % Proctor standar untuk tanah dasar, 90 % untuk timbunan biasa.",
  "Allowed water content deviation from OMC (± %)": "Toleransi kadar air terhadap OMC (± %)",
  "Empty: the water content is not checked.": "Kosong: kadar air tidak diperiksa.",
  "Specific gravity Gs (for the zero air voids line)": "Berat jenis Gs (untuk garis ZAV)",
