  "Checks the hole volume against the ASTM D1556 minimum.": "Memeriksa volume lubang terhadap minimum ASTM D1556.",
  "Water content from the oven masses, or typed in, or a speedy reading (% of wet mass).": "Kadar air dari massa oven, atau diisi langsung, atau bacaan speedy (% massa basah).",
  "Location / layer": "Lokasi / lapisan",
  "Wet soil from the hole (g)": "Tanah basah dari lubang (g)",
  "Speedy reading (%)": "Bacaan speedy (%)",
  "Test method for field density with the sand cone": "Cara uji kepadatan lapangan dengan alat konus pasir",
  "Density and unit weight of soil in place by sand-cone method": "Kepadatan dan berat isi tanah di tempat dengan metode sand cone",
  "Field determination of water content of soil by calcium carbide gas pressure tester": "Penentuan kadar air tanah di lapangan dengan alat uji tekanan gas kalsium karbida (speedy)",
  "A speedy reading must be below 100 %": "Bacaan speedy harus di bawah 100 %",
  "The calibration container volume must be above zero": "Volume wadah kalibrasi harus lebih dari nol",
  "Enter the bulk density of the sand, or the calibration container mass and volume": "Isi berat isi pasir, atau massa dan volume wadah kalibrasi",
  "Enter the mass of sand that fills the cone and base plate": "Isi massa pasir pengisi konus dan pelat dasar",
  "The bulk density of the sand should be between 1.0 and 2.0 g/cm³; check the calibration": "Berat isi pasir seharusnya 1,0–2,0 g/cm³; periksa kalibrasinya",
  "Enter at least one test point with the jar masses and the wet soil mass": "Isi minimal satu titik uji dengan massa botol dan massa tanah basah",
  "The sand used is not more than the sand in the cone; check the jar masses and the cone correction": "Pasir terpakai tidak lebih dari pasir di konus; periksa massa botol dan koreksi konus",
  "At some points the sand used is not more than the sand in the cone; those points are not calculated.": "Di beberapa titik pasir terpakai tidak lebih dari pasir di konus; titik tersebut tidak dihitung.",
  "No sand left in the hole: check the masses": "Tidak ada pasir di lubang: periksa massanya",
  "Oven masses not valid: wet ≥ dry > container": "Massa oven tidak valid: basah ≥ kering > kontainer",
  "Sand in the hole = (jar + sand before − jar + sand after) − sand in the cone; hole volume V = sand in the hole / ρ sand.": "Pasir di lubang = (botol + pasir awal − botol + pasir akhir) − pasir di konus; volume lubang V = pasir di lubang / ρ pasir.",
  "Wet density ρ = wet soil from the hole / V; dry density ρd = ρ / (1 + w/100); relative compaction RC = ρd / ρd,max × 100.": "Berat isi basah ρ = tanah basah dari lubang / V; berat isi kering ρd = ρ / (1 + w/100); derajat kepadatan RC = ρd / ρd,max × 100.",
  "Enter the maximum dry density of the Proctor test to get the relative compaction.": "Isi berat isi kering maksimum uji Proctor untuk mendapat derajat kepadatan.",
  "A point passes when its relative compaction reaches the specification.": "Titik lulus bila derajat kepadatannya memenuhi spesifikasi.",
  "A point also fails when its water content is further from the OMC than the allowed deviation.": "Titik juga tidak lulus bila kadar airnya menyimpang dari OMC melebihi toleransi.",
  "Speedy readings are converted from the wet-mass basis with w = R / (100 − R) × 100; check them against oven water contents (ASTM D4944).": "Bacaan speedy dikonversi dari basis massa basah dengan w = R / (100 − R) × 100; cek terhadap kadar air oven (ASTM D4944).",
  "Some holes are smaller than the ASTM D1556 minimum volume for the largest particle size; see the remark column.": "Beberapa lubang lebih kecil dari volume minimum ASTM D1556 untuk ukuran butir terbesar; lihat kolom keterangan.",
  "ASTM D1556 asks for at least three determinations of the sand bulk density; their average is used.": "ASTM D1556 meminta minimal tiga kali penentuan berat isi pasir; dipakai rata-ratanya.",
  "A wet density outside 1.2–2.6 g/cm³ is unusual for compacted soil; check the masses.": "Berat isi basah di luar 1,2–2,6 g/cm³ tidak lazim untuk tanah dipadatkan; periksa massanya.",
