  "Blows and penetration of the DCP: DCP index per interval and per layer, CBR by correlation, cumulative blows and CBR against depth.": "Pukulan dan penetrasi DCP: indeks DCP per interval dan per lapisan, CBR dari korelasi, grafik pukulan kumulatif dan CBR terhadap kedalaman.",
