  "Only when the readings do not start with a row of 0 blows.": "Hanya bila bacaan tidak diawali baris 0 pukulan.",
  "Depth of the test surface (mm)": "Kedalaman permukaan uji (mm)",
  "Below the reference level, e.g. after removing the surface layer; empty = 0.": "Di bawah level acuan, mis. setelah lapis permukaan dibongkar; kosong = 0.",
  "Surface / layer tested": "Permukaan / lapisan yang diuji",
  "One row per set of blows; the first row is usually 0 blows with the zero reading.": "Satu baris per set pukulan; baris pertama biasanya 0 pukulan dengan bacaan nol.",
  "Penetration reading (mm)": "Bacaan penetrasi (mm)",
  "Layer boundaries from the change of slope on the cumulative blows chart; empty = one layer.": "Batas lapisan dari perubahan kemiringan pada grafik pukulan kumulatif; kosong = satu lapisan.",
  "From (mm)": "Dari (mm)",
  "To (mm)": "Sampai (mm)",
  "Use of the dynamic cone penetrometer in shallow pavement applications": "Penggunaan dynamic cone penetrometer untuk perkerasan dangkal",
  "Guideline: CBR test method with the dynamic cone penetrometer (DCP)": "Pedoman cara uji CBR dengan dynamic cone penetrometer (DCP)",
  "Enter at least two readings (the zero reading and one set of blows)": "Isi minimal dua bacaan (bacaan nol dan satu set pukulan)",
  "Blows cannot be negative": "Jumlah pukulan tidak boleh negatif",
  "The cumulative blows must not decrease; check the blow counts": "Pukulan kumulatif tidak boleh berkurang; periksa jumlah pukulan",
  "The penetration readings must not decrease; check the readings": "Bacaan penetrasi tidak boleh berkurang; periksa bacaannya",
  "No set of blows with penetration was found": "Tidak ada set pukulan yang menghasilkan penetrasi",
  "The DCP index must be above zero": "Indeks DCP harus lebih dari nol",
  "A layer's bottom must be below its top": "Batas bawah lapisan harus di bawah batas atasnya",
  "DCP index DPI = penetration between two readings / blows × hammer factor (1 for the 8 kg hammer, 2 for the 4.6 kg hammer).": "Indeks DCP (DPI) = penetrasi antara dua bacaan / jumlah pukulan × faktor palu (1 untuk palu 8 kg, 2 untuk palu 4,6 kg).",
  "log CBR = 2.465 − 1.12 log DPI (ASTM D6951, all soils except CL with CBR < 10 and CH)": "log CBR = 2,465 − 1,12 log DPI (ASTM D6951, semua tanah kecuali CL dengan CBR < 10 dan CH)",
  "CBR = 1 / (0.017019 × DPI)² (ASTM D6951, CL soils with CBR < 10)": "CBR = 1 / (0,017019 × DPI)² (ASTM D6951, tanah CL dengan CBR < 10)",
  "CBR = 1 / (0.002871 × DPI) (ASTM D6951, CH soils)": "CBR = 1 / (0,002871 × DPI) (ASTM D6951, tanah CH)",
  "log CBR = 2.8135 − 1.313 log DCP (Indonesian DCP guideline, 60° cone)": "log CBR = 2,8135 − 1,313 log DCP (pedoman DCP Bina Marga, konus 60°)",
  "4.6 kg hammer: the DCP index is doubled before the correlation, as ASTM D6951 prescribes.": "Palu 4,6 kg: indeks DCP dikalikan dua sebelum masuk korelasi, sesuai ASTM D6951.",
  "A DCP index below 1 mm/blow means near refusal (gravel, rock or a very stiff layer); the CBR there is outside the correlation.": "Indeks DCP di bawah 1 mm/pukulan berarti hampir refusal (kerikil, batuan atau lapisan sangat keras); CBR di situ di luar rentang korelasi.",
  "CBR above 100 % is outside the range of the correlations; report it as > 100 %.": "CBR di atas 100 % di luar rentang korelasi; laporkan sebagai > 100 %.",
  "No layers were entered: one layer over the whole test is used. Enter the layer boundaries seen on the cumulative-blows chart to get a CBR per layer.": "Lapisan belum diisi: dipakai satu lapisan untuk seluruh uji. Isi batas lapisan dari grafik pukulan kumulatif untuk mendapat CBR per lapisan.",
  "The CBR from a DCP is an estimate; confirm design values with field or laboratory CBR tests.": "CBR dari DCP adalah perkiraan; pastikan nilai desain dengan uji CBR lapangan atau laboratorium.",
