  "Seawater counts as sulfate class S1 at least (ACI 318-19 Table 19.3.1.1).": "Air laut dihitung minimal sebagai kelas sulfat S1 (ACI 318-19 Tabel 19.3.1.1).",
  "SNI 2847:2019 (ACI 318-14) gives only the first S3 option: Type V plus pozzolan or slag, w/cm ≤ 0.45, f'c ≥ 31 MPa.": "SNI 2847:2019 (ACI 318-14) hanya memuat opsi S3 pertama: Jenis V ditambah pozolan atau slag, w/cm ≤ 0,45, f'c ≥ 31 MPa.",
  "Chloride above 500 ppm or seawater: treat reinforced concrete in contact with the ground as exposure class C2 (ACI 318-19 Table 19.3.2.1); engineer's judgement on the source of chlorides.": "Klorida di atas 500 ppm atau air laut: beton bertulang yang kontak dengan tanah diperlakukan sebagai kelas paparan C2 (ACI 318-19 Tabel 19.3.2.1); sumber klorida dinilai oleh engineer.",
  "Ground aggressive to steel: allow for corrosion of steel piles (sacrificial thickness, coating or cathodic protection) per FHWA-NHI-16-009 and AASHTO LRFD 10.7.5.": "Tanah agresif terhadap baja: perhitungkan korosi tiang baja (tebal korban, pelapisan atau proteksi katodik) sesuai FHWA-NHI-16-009 dan AASHTO LRFD 10.7.5.",
  "Not every corrosion indicator was measured; test pH, resistivity, chloride and sulfate for a full check.": "Belum semua indikator korosi diukur; uji pH, resistivitas, klorida dan sulfat untuk pemeriksaan lengkap.",
  "pH 5.5–8.5 in soil with high organic content is also a corrosion indicator (AASHTO LRFD 10.7.5).": "pH 5,5–8,5 pada tanah berkadar organik tinggi juga merupakan indikator korosi (AASHTO LRFD 10.7.5).",
  "pH below 5.5: acidic ground attacks concrete and steel; consider protection of buried concrete (ACI 201.2R).": "pH di bawah 5,5: tanah asam merusak beton dan baja; pertimbangkan perlindungan beton yang tertanam (ACI 201.2R).",
  "The most severe soil or water value governs the exposure class (ACI 318-19 19.3.1).": "Nilai tanah atau air yang paling berat menentukan kelas paparan (ACI 318-19 19.3.1).",
  "Water-soluble sulfate as SO₄ in percent of dry soil (ASTM C1580); 1 % = 10 000 mg/kg.": "Sulfat larut air sebagai SO₄ dalam persen tanah kering (ASTM C1580); 1 % = 10 000 mg/kg.",
  "Preliminary interpretation; to be checked by a geotechnical engineer.": "Interpretasi awal; harus diperiksa oleh ahli geoteknik.",
