  "Each falling-head trial needs the initial head, the final head and a time greater than zero": "Setiap percobaan falling head memerlukan tinggi tekan awal, tinggi tekan akhir dan waktu lebih dari nol",
  "The final head must be lower than the initial head and above zero": "Tinggi tekan akhir harus lebih rendah dari tinggi tekan awal dan di atas nol",
  "Enter at least one trial": "Isi minimal satu percobaan",
  "The dry mass is too large for the specimen volume and Gs": "Massa kering terlalu besar untuk volume benda uji dan Gs",
  "Coefficient of permeability k20": "Koefisien permeabilitas k20",
