  "k20 (cm/s)": "k20 (cm/detik)",
  "Coefficient of permeability per trial": "Koefisien permeabilitas per percobaan",
  "Mean": "Rata-rata",
  "k = Q·L / (A·h·t).": "k = Q·L / (A·h·t).",
  "k = a·L / (A·t) · ln(h1/h2).": "k = a·L / (A·t) · ln(h1/h2).",
  "k20 = kT · ηT/η20, with the viscosity of water at the test temperature (ASTM D2434 / D5084).": "k20 = kT · ηT/η20, dengan viskositas air pada suhu uji (ASTM D2434 / D5084).",
  "Degree of permeability after Terzaghi & Peck (1967).": "Tingkat permeabilitas menurut Terzaghi & Peck (1967).",
  "A trial differs from the mean by more than 25 %; ASTM D5084 asks for consistent trials before reporting.": "Ada percobaan yang menyimpang lebih dari 25 % dari rata-rata; ASTM D5084 meminta hasil percobaan yang konsisten sebelum dilaporkan.",
  "Run at least three trials (four for ASTM D5084) and report their mean.": "Lakukan minimal tiga percobaan (empat untuk ASTM D5084) dan laporkan rata-ratanya.",
  "Constant head suits coarse soils with less than 10 % fines (ASTM D2434); use falling head for fine soils.": "Constant head cocok untuk tanah berbutir kasar dengan butir halus kurang dari 10 % (ASTM D2434); gunakan falling head untuk tanah berbutir halus.",
  "ASTM D2434 constant head": "ASTM D2434 constant head",
  "Falling head, rigid or flexible wall (ASTM D5856 / D5084 method C)": "Falling head, dinding kaku atau fleksibel (ASTM D5856 / D5084 metode C)",
  "The conversion factor K must be between 5 and 60": "Faktor konversi K harus antara 5 dan 60",
  "Each specimen needs the distance D and the failure load P": "Setiap benda uji memerlukan jarak D dan beban runtuh P",
