  "D/W outside 0.3–1.0 for an axial, block or lump test (ASTM D5731); treat that result with care.": "D/W di luar 0,3–1,0 untuk uji aksial, blok atau bongkah (ASTM D5731); gunakan hasil tersebut dengan hati-hati.",
