  "R4 – Strong": "R4 – Kuat",
  "R5 – Very strong": "R5 – Sangat kuat",
  "R6 – Extremely strong": "R6 – Sangat kuat sekali",
  "Is = P / De²; De² = D² (diametral) or 4·W·D/π (axial, block, lump); Is(50) = (De/50)^0.45 · Is (ASTM D5731).": "Is = P / De²; De² = D² (diametral) atau 4·W·D/π (aksial, blok, bongkah); Is(50) = (De/50)^0,45 · Is (ASTM D5731).",
  "UCS from Is(50) is an estimate: K is about 20–25 for many rocks (ASTM D5731, ISRM 1985; 24 after Broch & Franklin 1972) and should be calibrated with UCS tests on the same rock.": "UCS dari Is(50) hanya perkiraan: K sekitar 20–25 untuk banyak batuan (ASTM D5731, ISRM 1985; 24 menurut Broch & Franklin 1972) dan sebaiknya dikalibrasi dengan uji UCS pada batuan yang sama.",
  "ASTM D5731 asks for at least 10 valid tests per sample (more for anisotropic or variable rock).": "ASTM D5731 meminta minimal 10 uji valid per contoh (lebih banyak untuk batuan anisotropik atau bervariasi).",
  "Size correction is most reliable for De between about 30 and 85 mm.": "Koreksi ukuran paling andal untuk De sekitar 30 sampai 85 mm.",
