  "Enter the mold area to use the settlement of the surcharge plate": "Isi luas cetakan untuk memakai penurunan pelat beban",
  "Check the mold mass, volume and settlement of the maximum density trials": "Periksa massa cetakan, volume dan penurunan pada percobaan kepadatan maksimum",
  "The density trials differ by more than 2 %; check the procedure.": "Hasil percobaan kepadatan berbeda lebih dari 2 %; periksa prosedurnya.",
  "The dry density must be greater than zero": "Kepadatan kering harus lebih besar dari nol",
  "Minimum index density ρd,min": "Kepadatan indeks minimum ρd,min",
