  "Relative density Dr": "Kepadatan relatif Dr",
  "Friction angle φ' estimate (Meyerhof 1956)": "Perkiraan sudut geser φ' (Meyerhof 1956)",
  "Dry densities": "Kepadatan kering",
  "Index density trials": "Percobaan kepadatan indeks",
  "Index density": "Kepadatan indeks",
  "Minimum": "Minimum",
  "Maximum": "Maksimum",
  "ρd (g/cm³)": "ρd (g/cm³)",
  "Dr (%)": "Dr (%)",
  "A dry density lies outside the index density range; check the field density or the index tests.": "Ada kepadatan kering di luar rentang kepadatan indeks; periksa kepadatan lapangan atau uji indeksnya.",
  "Enter a field or specimen dry density to get the relative density.": "Isi kepadatan kering lapangan atau benda uji untuk mendapatkan kepadatan relatif.",
  "Dr = ρd,max (ρd − ρd,min) / (ρd (ρd,max − ρd,min)) = (emax − e) / (emax − emin) (ASTM D4254).": "Dr = ρd,max (ρd − ρd,min) / (ρd (ρd,max − ρd,min)) = (emax − e) / (emax − emin) (ASTM D4254).",
  "Index densities apply to free-draining cohesionless soils with at most 15 % fines (ASTM D4253).": "Kepadatan indeks berlaku untuk tanah non-kohesif yang mudah mengalirkan air dengan butir halus maksimum 15 % (ASTM D4253).",
  "Density classes after Lambe & Whitman (1969); φ' = 28° + 0.15 Dr after Meyerhof (1956), an estimate.": "Kelas kepadatan menurut Lambe & Whitman (1969); φ' = 28° + 0,15 Dr menurut Meyerhof (1956), sebagai perkiraan.",
  "ASTM D4253 / D4254 minimum and maximum index density": "Kepadatan indeks minimum dan maksimum ASTM D4253 / D4254",
  "Crumb grades are 1 to 4": "Grade crumb adalah 1 sampai 4",
  "Choose a pinhole class D1, D2, ND4, ND3, ND2 or ND1": "Pilih kelas pinhole D1, D2, ND4, ND3, ND2 atau ND1",
  "Percent finer with dispersant must be greater than zero": "Persen lolos dengan dispersan harus lebih besar dari nol",
