  "Final pinhole diameter": "Diameter akhir lubang pinhole",
  "Crumb test: the highest grade observed governs (conservative).": "Uji crumb: grade tertinggi yang teramati yang menentukan (konservatif).",
  "Choose the pinhole class from the ASTM D4647 criteria (flow rate, effluent and final hole size).": "Pilih kelas pinhole menurut kriteria ASTM D4647 (debit, kekeruhan air keluaran dan ukuran akhir lubang).",
  "The most dispersive indicator governs: one dispersive result is enough to treat the soil as dispersive (Sherard et al. 1976; USBR practice).": "Indikator paling dispersif yang menentukan: satu hasil dispersif cukup untuk memperlakukan tanah sebagai dispersif (Sherard dkk. 1976; praktik USBR).",
  "Pinhole classes: D1, D2 dispersive; ND4, ND3 slightly to moderately dispersive; ND2, ND1 non-dispersive (ASTM D4647).": "Kelas pinhole: D1, D2 dispersif; ND4, ND3 sedikit sampai agak dispersif; ND2, ND1 non-dispersif (ASTM D4647).",
  "Percent dispersion: above 50 % dispersive, 30–50 % intermediate, below 30 % non-dispersive (Sherard et al. 1976).": "Persen dispersi: di atas 50 % dispersif, 30–50 % peralihan, di bawah 30 % non-dispersif (Sherard dkk. 1976).",
  "Dispersive or intermediate soil erodes in still water: protect embankments, dam cores and culverts (filters, lime or gypsum treatment) and have the design checked by a geotechnical engineer.": "Tanah dispersif atau peralihan tergerus bahkan di air tenang: lindungi timbunan, inti bendungan dan gorong-gorong (filter, perbaikan dengan kapur atau gipsum) dan minta desainnya diperiksa ahli geoteknik.",
  "ASTM D6572 crumb, ASTM D4647 pinhole and ASTM D4221 double hydrometer": "Crumb ASTM D6572, pinhole ASTM D4647 dan double hydrometer ASTM D4221",
  "Laboratory chemistry: sulfate exposure class S1 for concrete piles: Type II cement, w/cm ≤ 0.50, f'c ≥ 28 MPa (ACI 318-19 / SNI 2847:2019).": "Kimia laboratorium: kelas paparan sulfat S1 untuk tiang beton: semen Jenis II, w/cm ≤ 0,50, f'c ≥ 28 MPa (ACI 318-19 / SNI 2847:2019).",
  "Laboratory chemistry: sulfate exposure class S2 for concrete piles: Type V cement, w/cm ≤ 0.45, f'c ≥ 31 MPa (ACI 318-19 / SNI 2847:2019).": "Kimia laboratorium: kelas paparan sulfat S2 untuk tiang beton: semen Jenis V, w/cm ≤ 0,45, f'c ≥ 31 MPa (ACI 318-19 / SNI 2847:2019).",
  "Laboratory chemistry: sulfate exposure class S3 for concrete piles: Type V cement with pozzolan or slag, w/cm ≤ 0.45, f'c ≥ 31 MPa (ACI 318-19 / SNI 2847:2019).": "Kimia laboratorium: kelas paparan sulfat S3 untuk tiang beton: semen Jenis V dengan pozolan atau slag, w/cm ≤ 0,45, f'c ≥ 31 MPa (ACI 318-19 / SNI 2847:2019).",
  "Laboratory chemistry: the ground is aggressive to steel; allow for corrosion of steel piles (FHWA-NHI-16-009, AASHTO LRFD 10.7.5).": "Kimia laboratorium: tanah agresif terhadap baja; perhitungkan korosi tiang baja (FHWA-NHI-16-009, AASHTO LRFD 10.7.5).",
  "φ' = {phi}° from the relative density of sample {s} (Dr = {dr} %, Meyerhof 1956); c = 0.": "φ' = {phi}° dari kepadatan relatif contoh {s} (Dr = {dr} %, Meyerhof 1956); c = 0.",
  "Concrete in contact with the ground: sulfate exposure class {c} (sample {s}, ACI 318-19 / SNI 2847:2019).": "Beton yang kontak dengan tanah: kelas paparan sulfat {c} (contoh {s}, ACI 318-19 / SNI 2847:2019).",
  "The ground is aggressive to steel (sample {s}).": "Tanah agresif terhadap baja (contoh {s}).",
  "Dispersive clay in sample {s}: protect against internal erosion.": "Lempung dispersif pada contoh {s}: lindungi terhadap erosi internal (piping).",
