  "Group {group}: DATA row before the HEADING row (AGS4 rule 3); it is skipped.": "Grup {group}: baris DATA sebelum baris HEADING (aturan AGS4 no. 3); dilewati.",
  "Line {line} ({group}): the DATA row has {n} fields and the HEADING row {m} (AGS4 rule 4); the row is skipped.": "Baris {line} ({group}): baris DATA berisi {n} kolom sedangkan baris HEADING {m} (aturan AGS4 no. 4); baris dilewati.",
  "Line {line} starts with '{word}' instead of GROUP, HEADING, UNIT, TYPE or DATA (AGS4 rule 3); it is skipped.": "Baris {line} diawali '{word}', bukan GROUP, HEADING, UNIT, TYPE atau DATA (aturan AGS4 no. 3); dilewati.",
