  "AGS3 file: read with the AGS3 group names converted (HOLE → LOCA, WSTK → WSTG); check the result.": "File AGS3: dibaca dengan nama grup AGS3 dikonversi (HOLE → LOCA, WSTK → WSTG); periksa hasilnya.",
  "Group {group}: unit '{unit}' of {heading} is not understood; values are taken as {expected}.": "Grup {group}: satuan '{unit}' pada {heading} tidak dikenal; nilai dianggap dalam {expected}.",
  "Group {group}: {heading} converted from {unit} to {expected}.": "Grup {group}: {heading} dikonversi dari {unit} ke {expected}.",
  "Group {group} has no {heading} heading (key field, AGS4 rule 10a); the group is skipped.": "Grup {group} tidak memiliki kolom {heading} (kolom kunci, aturan AGS4 10a); grup dilewati.",
  "Line {line} ({group}): LOCA_ID is empty (AGS4 rule 10b); the row is skipped.": "Baris {line} ({group}): LOCA_ID kosong (aturan AGS4 10b); baris dilewati.",
  "Line {line} ({group}): same key fields as line {other} (AGS4 rule 10a); the row is skipped.": "Baris {line} ({group}): kolom kunci sama dengan baris {other} (aturan AGS4 10a); baris dilewati.",
  "Group {group}: {n} rows refer to a LOCA_ID that is not in LOCA (AGS4 rule 10c); they are skipped.": "Grup {group}: {n} baris merujuk LOCA_ID yang tidak ada di LOCA (aturan AGS4 10c); dilewati.",
