  "The file names no project (PROJ_NAME); the boreholes go to 'Imported project'. Enter a project name to change it.": "File tidak menyebut nama proyek (PROJ_NAME); titik bor masuk ke 'Imported project'. Isi nama proyek untuk mengubahnya.",
