  "Samples of type {types} are not imported (the app keeps the AGS4 types U, UT, TW, P, D, B, SPTLS, C, W).": "Sampel jenis {types} tidak diimpor (aplikasi memakai jenis AGS4 U, UT, TW, P, D, B, SPTLS, C, W).",
