  "The findings apply to the test locations and the dates of the investigation. Ground conditions between and beyond the test points can differ. The analyses are preliminary, are based on the parameters stated in this report and must be checked by the design engineer of record. Groundwater levels vary with season and construction. The company should be informed if conditions differ from those described.": "Temuan berlaku untuk titik uji dan tanggal penyelidikan. Kondisi tanah di antara dan di luar titik uji bisa berbeda. Analisis bersifat pendahuluan, berdasarkan parameter yang dicantumkan dalam laporan ini, dan harus diperiksa oleh perencana yang bertanggung jawab. Muka air tanah berubah menurut musim dan kegiatan konstruksi. Mohon kami diberi tahu bila kondisi di lapangan berbeda dari uraian ini.",
  "The project of this report was not found": "Proyek laporan ini tidak ditemukan",
  "The report to the client: an outline per project type, filled from the project's boreholes, CPT, lab results and analyses, with your text. Approved reports are sealed and can be checked by the client.": "Laporan untuk klien: kerangka per jenis proyek, diisi dari titik bor, sondir, hasil lab dan analisis proyek, ditambah teks Anda. Laporan yang disetujui disegel dan bisa dicek keasliannya oleh klien.",
  "This page confirms that the document was issued as stated. Compare the number, title and date with your copy; it shows no technical data.": "Halaman ini memastikan dokumen diterbitkan seperti yang tertera. Cocokkan nomor, judul dan tanggal dengan salinan Anda; halaman ini tidak menampilkan data teknis.",
  "USCS class recorded on each log.": "Kelas USCS yang dicatat pada tiap log.",
  "Use the outline of this project type": "Pakai kerangka jenis proyek ini",
