  "Versions": "Versi",
  "What changed in this version.": "Apa yang berubah pada versi ini.",
  "Who can sign in. Field users add logs and change their own; the laboratory records test results; project leaders run projects, quotations, contracts and reports; finance handles invoices; administrators can do everything and manage users; client accounts only see the issued reports of their own projects.": "Siapa yang bisa masuk. Pengguna lapangan menambah log dan mengubah log miliknya; laboratorium mencatat hasil uji; pimpinan proyek mengelola proyek, penawaran, kontrak, dan laporan; keuangan menangani invoice; administrator bisa melakukan semuanya dan mengelola pengguna; akun klien hanya melihat laporan terbit dari proyeknya sendiri.",
  "Write the revision note: what changed in this version": "Isi catatan revisi: apa yang berubah pada versi ini",
